function validate([stream, pattern]) {
  if (!Array.isArray(stream) || stream.length < 1 || stream.length > 2000) return 'The repeating stream block needs 1 to 2000 bits.';
  if (!Array.isArray(pattern) || pattern.length < 1 || pattern.length > 10000) return 'pattern needs 1 to 10^4 bits.';
  if (stream.some(b => b !== 0 && b !== 1)) return 'The stream contains only 0 and 1.';
  if (pattern.some(b => b !== 0 && b !== 1)) return 'pattern contains only 0 and 1.';
  const text = Array.from({ length: stream.length + pattern.length - 1 }, (_, i) => stream[i % stream.length]).join('');
  if (!text.includes(pattern.join(''))) return 'pattern must appear somewhere in the repeating stream.';
  return null;
}

