function adapt(input, solve, kit) {
  const [block, pattern] = input;
  const limit = 110000;
  let reads = 0;
  // The block is hidden in this closure; the solution sees it only one bit at a time.
  const infiniteStream = Object.freeze({
    next() {
      if (reads >= limit) throw new Error('next() was called more than 110000 times; the pattern starts within the first 10^5 bits.');
      const bit = block[reads % block.length];
      reads++;
      return bit;
    },
  });
  const answer = solve(infiniteStream, pattern.slice());
  if (!Number.isInteger(answer)) throw new Error('Return the starting position as an integer.');
  return answer;
}

