function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 1200 + Math.floor(rand() * 801) : 1 + Math.floor(rand() * 7);
  const style = Math.floor(rand() * 3);
  let stream;
  if (style === 0) {
    // Mostly ones with rare zeros: long partial matches that keep failing.
    stream = Array.from({ length: n }, () => (rand() < 0.92 ? 1 : 0));
  } else if (style === 1) {
    // A short motif repeated with a few flipped bits.
    const motif = Array.from({ length: 1 + Math.floor(rand() * 5) }, () => (rand() < 0.5 ? 1 : 0));
    stream = Array.from({ length: n }, (_, i) => (rand() < 0.03 ? 1 - motif[i % motif.length] : motif[i % motif.length]));
  } else {
    stream = Array.from({ length: n }, () => (rand() < 0.5 ? 1 : 0));
  }
  const m = large ? 1 + Math.floor(rand() * 2000) : 1 + Math.floor(rand() * 6);
  // Copy the pattern out of the repeating stream so it is sure to occur.
  const start = Math.floor(rand() * n);
  const pattern = Array.from({ length: m }, (_, i) => stream[(start + i) % n]);
  return [stream, pattern];
}
